<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>دسته‌ها و برندها | گره</title><link rel="stylesheet" href="<?= base_url('assets/css/app.css') ?>"></head><body class="min-h-screen bg-[#f5f5f2] text-gereh-900"><main class="gereh-container py-8"><a href="<?= site_url('admin') ?>" class="gereh-muted">← پیشخوان</a><h1 class="my-6 text-2xl font-bold">مدیریت دسته‌بندی‌ها و برندها</h1><?php if(session()->getFlashdata('error')): ?><p class="mb-4 rounded-xl bg-red-50 p-4 text-red-800"><?= esc(session()->getFlashdata('error')) ?></p><?php endif; ?><?php if(session()->getFlashdata('success')): ?><p class="mb-4 rounded-xl bg-green-50 p-4 text-green-800"><?= esc(session()->getFlashdata('success')) ?></p><?php endif; ?><div class="grid gap-5 md:grid-cols-2"><?php foreach([['title'=>'دسته‌بندی‌ها','type'=>'categories','items'=>$categories],['title'=>'برندها','type'=>'brands','items'=>$brands]] as $group): ?><section class="gereh-card p-6"><h2 class="mb-5 text-lg font-bold"><?= esc($group['title']) ?></h2><form action="<?= site_url('admin/taxonomy/'.$group['type']) ?>" method="post" class="mb-6 space-y-3"><?= csrf_field() ?><label class="block text-sm">نام<input class="gereh-input mt-1" name="name" maxlength="160" required></label><label class="block text-sm">شناسه انگلیسی<input class="gereh-input mt-1" name="slug" pattern="[a-z0-9-]+" maxlength="190" required></label><button class="gereh-button" type="submit">افزودن</button></form><ul class="divide-y divide-gereh-cream"><?php foreach($group['items'] as $item): ?><li class="flex justify-between gap-3 py-3 text-sm"><span><?= esc($item['name']) ?></span><span class="gereh-muted" dir="ltr"><?= esc($item['slug']) ?></span></li><?php endforeach; ?></ul></section><?php endforeach; ?></div></main></body></html>